  async function load(){const query=new URLSearchParams({audience,q:state.query,...Object.fromEntries(Object.entries(state.filters).filter(([,v])=>v))});state.catalog=await api(`/api/resources?${query}`);if(state.versionId)state.detail=await api(`/api/resources/${encodeURIComponent(state.versionId)}?audience=${audience}`);render();}
