    if(kind==='download')download(await api(`/api/resource-files/${button.dataset.id}/download?audience=${audience}`,{method:'POST',body:{},binary:true}),(state.detail.files||[]).find(file=>file.id===button.dataset.id)?.filename||'publication');
    if(kind==='analyze-ai'){state.analysis=await api(`/api/resources/${state.versionId}/analyze`,{method:'POST',body:{ai:true}});await load();}
    if(kind==='analyze'){state.analysis=await api(`/api/resources/${state.versionId}/analyze`,{method:'POST',body:{}});await load();}
